            do = md(ox, oy, tx, ty)
            # Prefer resources where we are relatively closer (do - ds large),
            # then prefer closer resources for faster collection.
            key = (do - ds, -ds, tx, ty)
            if best is None or key > best[0]:
                best = (key, tx, ty)
        return best[1], best[2]

    tx, ty = best_target()

    best_move = [0, 0]
