                continue
            if (nx, ny) in obstacles:
                continue
            ns = md(nx, ny, tx, ty)
            no = md(ox, oy, tx, ty)

            # Compare progress vs opponent: maximize relative advantage after move.
            # Small bias toward staying nearer to current best target.
            rel = (no - ns)
